 "content": "def transform(grid):
    """Restore zero-masked cells from the row mirrored across the horizontal axis."""
    h = len(grid)
    out = [row[:] for row in grid]
    for r in range(h):
        for c, value in enumerate(grid[r]):
            if value == 0:
                out[r][c] = grid[h - 1 - r][c]
    return out
